steps.codeExample:
var env string

var deployCmd = &cobra.Command{
    Use:   "deploy",
    Short: "Faz deploy da aplicação",
    RunE: func(cmd *cobra.Command, args []string) error {
        fmt.Println("Deploy em:", env)
        return nil
    },
}

func init() {
    deployCmd.Flags().StringVarP(&env, "env", "e", "staging", "Ambiente alvo")
    rootCmd.AddCommand(deployCmd)
}

